import unittest
import random
import torch
from pyvene import CausalModel
random.seed(42)


class CasualModelTestCase(unittest.TestCase):
    @classmethod
    def setUpClass(self):
        print("=== Test Suite: CausalModelTestCase ===")
        self.variables = ['A', 'B', 'C']
        self.values = {
            'A': [False, True],
            'B': [False, True],
            'C': [False, True]
        }

        self.parents = {
            'A': [],
            'B': [],
            'C': ['A', 'B']
        }

        self.functions = {
            "A": lambda: True,
            "B": lambda: True,
            "C": lambda a, b: a and b
        }

        self.causal_model = CausalModel(
            self.variables, 
            self.values, 
            self.parents, 
            self.functions
        )
        self.causal_model.generate_equiv_classes()

    def test_initialization(self):
        inputs = ['A', 'B']
        outputs = ['C']
        timesteps = {
            'A': 0,
            'B': 0,
            'C': 1
        }
        equivalence_classes = {
            'C': {
                False: [
                    {'A': False, 'B': False},
                    {'A': False, 'B': True},
                    {'A': True, 'B': False}
                ],
                True: [
                    {'A': True, 'B': True}
                ]
            }
        }

        self.assertEqual(set(self.causal_model.inputs), set(inputs))
        self.assertEqual(set(self.causal_model.outputs), set(outputs))
        self.assertEqual(self.causal_model.timesteps, timesteps)
        self.assertEqual(self.causal_model.equiv_classes, equivalence_classes)

    def test_run_forward(self):
        # test run forward with default values (A and B set to True)
        self.assertEqual(
            self.causal_model.run_forward(),
            {'A': True, 'B': True, 'C': True}
        )

        # test run forward on all possible input values
        for a in [False, True]:
            for b in [False, True]:
                input_setting = {
                    'A': a,
                    'B': b
                }
                output_setting = {
                    'A': a,
                    'B': b,
                    'C': a and b
                }
                self.assertEqual(self.causal_model.run_forward(input_setting), output_setting)

        # test run forward on fully specified setting
        output_setting = {'A': False, 'B': False, 'C': True}
        self.assertEqual(self.causal_model.run_forward(output_setting), output_setting)

    def test_run_interchange(self):
        # interchange intervention on input
        base = {'A': True, 'B': False}
        source = {'A': False, 'B': True}
        self.assertEqual(self.causal_model.run_forward(base)['C'], False)
        self.assertEqual(self.causal_model.run_forward(source)['C'], False)
        self.assertEqual(
            self.causal_model.run_interchange(base, {'B': source})['C'],
            True
        )

        # interchange intervention on output
        base = {'A': False, 'B': False}
        source = {'A': True, 'B': True}
        self.assertEqual(self.causal_model.run_forward(base)['C'], False)
        self.assertEqual(
            self.causal_model.run_interchange(base, {'B': source})['C'],
            False
        )
        self.assertEqual(
            self.causal_model.run_interchange(base, {'C': source})['C'],
            True
        )

    def test_sample_input_tree_balanced(self):
        # NOTE: not quite sure how to test a function with random behavior
        # right now, fixing seed and assuming approximate behavior 
        # (taking balanced to be less than 30-70 split)

        K = 100
        # test sampling by output value
        outputs = []
        for _ in range(K):
            sample = self.causal_model.sample_input_tree_balanced()
            output = self.causal_model.run_forward(sample)
            outputs.append(output['C'])
        self.assertGreaterEqual(sum(outputs), 30)
        self.assertLessEqual(sum(outputs), 70)

        # test sampling by input value
        inputs = []
        for _ in range(K):
            sample = self.causal_model.sample_input_tree_balanced()
            inputs.append(sample['A'])
        self.assertGreaterEqual(sum(outputs), 30)
        self.assertLessEqual(sum(outputs), 70)

    def test_generate_factual_dataset(self):
        def sampler():
            return {'A': False, 'B': False}

        size = 4
        factual_dataset = self.causal_model.generate_factual_dataset(
            size=size,
            sampler=sampler,
            return_tensors=False
        )
        self.assertEqual(len(factual_dataset), size)

        self.assertEqual(factual_dataset[0]['input_ids'], {'A': False, 'B': False})
        self.assertEqual(factual_dataset[0]['labels']['C'], False)

        factual_dataset_tensors = self.causal_model.generate_factual_dataset(
            size=size,
            sampler=sampler,
            return_tensors=True
        )
        self.assertEqual(len(factual_dataset_tensors), size)
        X = torch.stack([example['input_ids'] for example in factual_dataset_tensors])
        y = torch.stack([example['labels'] for example in factual_dataset_tensors])
        self.assertEqual(X.shape, (size, 2))
        self.assertEqual(y.shape, (size, 1))
        self.assertTrue(torch.equal(X[0], torch.tensor([0., 0.])))
        self.assertTrue(torch.equal(y[0], torch.tensor([0.])))

    def test_generate_counterfactual_dataset(self):
        def sampler(*args, **kwargs):
            if kwargs.get('output_var', None):
                return {'A': True, 'B': True}

            return {'A': True, 'B': False}

        def intervention_sampler(*args, **kwargs):
            return {'B': True}

        def intervention_id(*args, **kwargs):
            return 0

        size = 4
        counterfactual_dataset = self.causal_model.generate_counterfactual_dataset(
            size=size,
            batch_size=1,
            intervention_id=intervention_id,
            sampler=sampler,
            intervention_sampler=intervention_sampler,
            return_tensors=False
        )
        self.assertEqual(len(counterfactual_dataset), size)
        example = counterfactual_dataset[0]
        self.assertEqual(example['input_ids'], {'A': True, 'B': False})
        self.assertEqual(example['source_input_ids'][0]['B'], True)
        self.assertEqual(example['intervention_id'], [0])
        self.assertEqual(example['base_labels']['C'], False) # T and F
        self.assertEqual(example['labels']['C'], True) # T and T


def suite():
    suite = unittest.TestSuite()
    suite.addTest(CasualModelTestCase("test_initialization"))
    suite.addTest(CasualModelTestCase("test_run_forward"))
    suite.addTest(CasualModelTestCase("test_run_interchange"))
    suite.addTest(CasualModelTestCase("test_sample_input_tree_balanced"))
    suite.addTest(CasualModelTestCase("test_generate_factual_dataset"))
    suite.addTest(CasualModelTestCase("test_generate_counterfactual_dataset"))
    return suite


if __name__ == "__main__":
    runner = unittest.TextTestRunner()
    runner.run(suite())

from abc import ABCMeta, abstractmethod

import torch


class InverseRotateLayer(torch.nn.Module):
    """The inverse of a given `LinearLayer` module."""

    def __init__(self, lin_layer):
        super().__init__()
        self.lin_layer = lin_layer

    def forward(self, x):
        output = torch.matmul(x, self.lin_layer.weight.T)
        return output


class RotateLayer(torch.nn.Module):
    """A linear transformation with orthogonal initialization."""

    def __init__(self, n, init_orth=True):
        super().__init__()
        weight = torch.empty(n, n)
        # we don't need init if the saved checkpoint has a nice
        # starting point already.
        # you can also study this if you want, but it is our focus.
        if init_orth:
            torch.nn.init.orthogonal_(weight)
        self.weight = torch.nn.Parameter(weight, requires_grad=True)

    def forward(self, x):
        return torch.matmul(x.to(self.weight.dtype), self.weight)


class LowRankRotateLayer(torch.nn.Module):
    """A linear transformation with orthogonal initialization."""

    def __init__(self, n, m, init_orth=True):
        super().__init__()
        # n > m
        self.weight = torch.nn.Parameter(torch.empty(n, m), requires_grad=True)
        if init_orth:
            torch.nn.init.orthogonal_(self.weight)

    def forward(self, x):
        return torch.matmul(x.to(self.weight.dtype), self.weight)


class SubspaceLowRankRotateLayer(torch.nn.Module):
    """A linear transformation with orthogonal initialization with subspace."""

    def __init__(self, n, m, init_orth=True):
        super().__init__()
        # n > m
        self.weight = torch.nn.Parameter(torch.empty(n, m), requires_grad=True)
        if init_orth:
            torch.nn.init.orthogonal_(self.weight)

    def forward(self, x, l, r):
        return torch.matmul(x.to(self.weight.dtype), self.weight[:, l:r])


class AutoencoderLayerBase(torch.nn.Module, metaclass=ABCMeta):
    """An abstract base class that defines an interface of an autoencoder."""

    @abstractmethod
    def encode(self, x):
        ...

    @abstractmethod
    def decode(self, latent):
        ...


class AutoencoderLayer(AutoencoderLayerBase):
    """An autoencoder with a single-layer encoder and single-layer decoder."""
    def __init__(self, input_dim, latent_dim, **kwargs):
        super().__init__()
        self.input_dim = input_dim
        self.latent_dim = latent_dim
        self.encoder = torch.nn.Sequential(
              torch.nn.Linear(input_dim, latent_dim, bias=True),
              torch.nn.ReLU())
        self.decoder = torch.nn.Sequential(
              torch.nn.Linear(latent_dim, input_dim, bias=True))

    def encode(self, x):
        x = x.to(self.encoder[0].weight.dtype)
        x = x - self.decoder[0].bias
        latent = self.encoder(x)
        return latent

    def decode(self, latent):
        return self.decoder(latent)

    def forward(self, base, return_latent=False):
        base_type = base.dtype
        base = base.to(self.encoder[0].weight.dtype)
        latent = self.encode(base)
        base_reconstruct = self.decode(latent)
        if not return_latent:
            return base_reconstruct.to(base_type)
        return {'latent': latent, 'output': base_reconstruct}

import json
import torch

class InterventionState(object):
    def __init__(self, key, **kwargs):
        self.key = key
        self.reset()

    def inc_getter_version(self):
        self.state_dict["getter_version"] += 1

    def inc_setter_version(self):
        self.state_dict["setter_version"] += 1

    def getter_version(self):
        return self.state_dict["getter_version"]

    def setter_version(self):
        return self.state_dict["setter_version"]

    def get_states(self):
        return self.state_dict

    def set_state(self, state_dict):
        self.state_dict = state_dict

    def reset(self):
        self.state_dict = {
            "key": self.key,
            "getter_version": 0,
            "setter_version": 0,
        }

    def __repr__(self):
        return json.dumps(self.state_dict, indent=4)

    def __str__(self):
        return json.dumps(self.state_dict, indent=4)

def broadcast_tensor_v1(x, target_shape):
    # Ensure the last dimension of target_shape matches x's size
    if target_shape[-1] != x.shape[-1]:
        raise ValueError("The last dimension of target_shape must match the size of x")

    # Create a shape for reshaping x that is compatible with target_shape
    reshape_shape = [1] * (len(target_shape) - 1) + [x.shape[-1]]

    # Reshape x and then broadcast it
    x_reshaped = x.view(*reshape_shape)
    broadcasted_x = x_reshaped.expand(*target_shape)
    return broadcasted_x

def broadcast_tensor_v2(x, target_shape):
    # Ensure that target_shape has at least one dimension
    if len(target_shape) < 1:
        raise ValueError("Target shape must have at least one dimension")

    # Extract the first n-1 dimensions from the target shape
    target_dims_except_last = target_shape[:-1]

    # Broadcast the input tensor x to match the target_dims_except_last and keep its last dimension
    broadcasted_x = x.expand(*target_dims_except_last, x.shape[-1])

    return broadcasted_x

def _can_cast_tensor(
    subspaces
):
    tensorfiable = True
    try:
        torch.tensor(subspaces)
    except:
        tensorfiable = False

    return tensorfiable

def _can_use_fast(
    subspaces
):
    tensorfiable = True
    row_same_val = False
    try:
        subspaces = torch.tensor(subspaces)
        row_same_val = torch.all(subspaces == subspaces[0], axis=1).all()
    except:
        tensorfiable = False

    return row_same_val and tensorfiable

def _do_intervention_by_swap(
    base,
    source,
    mode="interchange",
    interchange_dim=None,
    subspaces=None,
    subspace_partition=None,
    use_fast=False,
):
    """The basic do function that guards interventions"""
    if mode == "collect":
        assert source is None
    else:
        # auto broadcast
        if base.shape != source.shape:
            try:
                source = broadcast_tensor_v1(source, base.shape)
            except:
                raise ValueError(
                    f"source with shape {source.shape} cannot be broadcasted "
                    f"into base with shape {base.shape}."
                )
    # if subspace is none, then we are doing swap based on interchange_dim
    if subspaces is None:
        if mode == "interchange":
            base[..., :interchange_dim] = source[..., :interchange_dim]
        elif mode == "add":
            base[..., :interchange_dim] += source[..., :interchange_dim]
        elif mode == "subtract":
            base[..., :interchange_dim] -= source[..., :interchange_dim]
        elif mode == "collect":
            return base[..., :interchange_dim] # return without side-effect
        return base

    sel_subspace_indices = None
    if use_fast or _can_use_fast(subspaces):
        # its tensor, and each row the same
        if subspace_partition is None:
            sel_subspace_indices = subspaces[0]
        else:
            sel_subspace_indices = []
            for subspace in subspaces[0]:
                sel_subspace_indices.extend(
                    subspace_partition[subspace]
                )
    elif _can_cast_tensor(subspaces):
        sel_subspace_indices = []
        for example_i in range(len(subspaces)):
            # render subspace as column indices
            if subspace_partition is None:
                sel_subspace_indices.append(subspaces[example_i])
            else:
                _sel_subspace_indices = []
                for subspace in subspaces[example_i]:
                    _sel_subspace_indices.extend(
                        subspace_partition[subspace]
                    )
                sel_subspace_indices.append(_sel_subspace_indices)

    # _can_use_fast or _can_cast_tensor will prepare the sel_subspace_indices
    if sel_subspace_indices is not None:
        pad_idx = torch.arange(base.shape[-2]).unsqueeze(dim=-1).to(base.device)
        if mode == "interchange":
            base[..., pad_idx, sel_subspace_indices] = source[..., pad_idx, sel_subspace_indices]
        elif mode == "add":
            base[..., pad_idx, sel_subspace_indices] += source[..., pad_idx, sel_subspace_indices]
        elif mode == "subtract":
            base[..., pad_idx, sel_subspace_indices] -= source[..., pad_idx, sel_subspace_indices]
        elif mode == "collect":
            return base[..., pad_idx, sel_subspace_indices] # return without side-effect
    else:
        collect_base = []
        for example_i in range(len(subspaces)):
            # render subspace as column indices
            if subspace_partition is None:
                sel_subspace_indices = subspaces[example_i]
            else:
                sel_subspace_indices = []
                for subspace in subspaces[example_i]:
                    sel_subspace_indices.extend(
                        subspace_partition[subspace]
                    )
            if mode == "interchange":
                base[example_i, ..., sel_subspace_indices] = source[
                    example_i, ..., sel_subspace_indices
                ]
            elif mode == "add":
                base[example_i, ..., sel_subspace_indices] += source[
                    example_i, ..., sel_subspace_indices
                ]
            elif mode == "subtract":
                base[example_i, ..., sel_subspace_indices] -= source[
                    example_i, ..., sel_subspace_indices
                ]
            elif mode == "collect":
                collect_base += [base[example_i, ..., sel_subspace_indices]]
        if mode == "collect":
            return torch.stack(collect_base, dim=0) # return without side-effect

    return base

